      border: 1px solid var(--wa-line);
      border-radius: 999px;
      padding: .4rem .72rem;
      color: var(--wa-muted);
      background: rgba(255, 255, 255, .025);
      cursor: pointer;
      font: inherit;
      white-space: nowrap;
